def _ddm_ok(db):
    company = _ddm_company(db, "GDDMO")
    _ddm_facts(db, company, DDM_FACTS)
    _ddm_price(db, company, 30.0)
    engine = DividendDiscountEngine()
    return engine.value(engine.build_context(db, company, 30.0))


def _ddm_insufficient(db):
    company = _ddm_company(db, "GDDMI")
    _ddm_facts(db, company, {"net_income": 300.0})
    _ddm_price(db, company, 30.0)
    engine = DividendDiscountEngine()
    return engine.value(engine.build_context(db, company, 30.0))


