    company = _ddm_company(db, "GDDMK")
    _ddm_facts(db, company, {**DDM_FACTS, "cost_of_equity": 0.02})
    _ddm_price(db, company, 30.0)
    engine = DividendDiscountEngine()
    return engine.value(engine.build_context(db, company, 30.0))


