def _synthetic_fact(metric, value, *, period="FY2025", fiscal_year=2025):
    return FinancialFact(
        metric=metric,
        value=Decimal(str(value)),
        unit="USD",
        period=period,
        fiscal_year=fiscal_year,
        fiscal_quarter="FY",
        source_type="golden_test",
        is_reported=True,
        confidence=Decimal("0.90"),
    )


def _coherent_snapshot_sin_net_debt():
    """Snapshot coherente en todo menos net_debt.

    El builder real marca net_debt como REQUIRED_FOR_DCF, asi que un snapshot
    construido por el nunca es coherent=True sin net_debt: la guarda de
    net_debt de standard_dcf y pre_revenue (el bloque fusionado) es
    inalcanzable por esa via. Este snapshot sintetico ejercita la guarda tal
    cual, para que el golden cubra tambien el bloque refactorizado.
    """
    facts = {
        metric: _synthetic_fact(metric, value)
        for metric, value in {
            "revenue": 1000,
            "free_cash_flow": 120,
            "revenue_growth": 0.07,
            "shares_diluted": 100,
        }.items()
    }
    return FinancialSnapshot(
        as_of_period="FY2025",
        fiscal_year=2025,
        fiscal_quarter="FY",
        period_type="FY",
        facts=facts,
        missing_inputs=["net_debt"],
        coherent=True,
    )


def _dcf_net_debt_guard(db):
    company = _make_company(db, "GDCFG", company_type="standard", valuation_model="standard_dcf")
    _add_traceable_wacc(db, company)
    engine = StandardDCFEngine()
    context = ValuationContext(
        db=db,
        company=company,
        snapshot=_coherent_snapshot_sin_net_debt(),
        current_price=20.0,
        engine_key=engine.key,
    )
    return engine.value(context)


def _prerev_net_debt_guard(db):
    company = _make_company(
        db,
        "GPRVG",
        company_type="pre_revenue",
        valuation_model="probability_weighted_scenarios",
        factor_tags=["pre_fcf", "speculative"],
    )
    _add_traceable_wacc(db, company)
    engine = PreRevenueScenarioEngine()
    context = ValuationContext(
        db=db,
        company=company,
        snapshot=_coherent_snapshot_sin_net_debt(),
        current_price=30.0,
        engine_key=engine.key,
    )
    return engine.value(context)


