# GOLDENS_END

GOLDENS = json.loads(GOLDENS_JSON)
# Exact alternative captured from unmodified main at the recorded SHA on the VM.
# Python/runtime reductions differ in the final floating point digits. Compare
# the entire serialized result against either known baseline, never round values
# or use a tolerance that could hide a changed financial field.
_VM_BASELINE = json.loads(
    (Path(__file__).parent / "fixtures/valuation/golden-python312-arm64.json").read_text()
)["cases"]


@pytest.mark.parametrize("case", sorted(CASES))
def test_engine_output_matches_golden(db, case):
    golden = GOLDENS.get(case)
    assert golden is not None, f"falta el valor fijo de {case}: regenera GOLDENS_JSON desde main"
    actual = _dump(CASES[case](db))
    assert actual in {golden, _VM_BASELINE.get(case, golden)}


@pytest.mark.parametrize("case", sorted(CASES))
def test_zz_generate_golden(db, case):
    """Genera los valores fijos. Solo corre con GOLDEN_GEN=1 (sobre main)."""
    if not os.environ.get("GOLDEN_GEN"):
        pytest.skip("generador desactivado")
    out = Path(os.environ.get("GOLDEN_OUT", "/tmp/goldens.jsonl"))
    with out.open("a") as handle:
        handle.write(json.dumps({"case": case, "golden": _dump(CASES[case](db))}) + "\n")
